    owner: remembered.owner,
    repo: remembered.repo,
    number: remembered.number,
    branch: remembered.branch,
  },
}];

"use strict";

// Only the service code may change. Tests are off limits: a model that can
// edit tests/ can make a red check green by weakening the check.
const ALLOWED_PREFIX = /^app\//;

// Small models stop mid-string, or emit the closing braces before the closing
// quote. A quote ends a string only when what follows can legally follow one.
function repairJson(text) {
  let out = "";
  let inString = false;
  let escaped = false;
  let stringRole = "key";
  const stack = [];
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inString) {
      if (escaped) {
        out += c;
        escaped = false;
        continue;
      }
      if (c === "\\") {
        out += c;
        escaped = true;
        continue;
      }
      if (c === '"') {
        const rest = text.slice(i + 1);
        // "broken"}","new" — the quote before } is inside the value.
        if (/^\s*\}"/.test(rest)) {
          out += '\\"';
          continue;
        }
        let j = i + 1;
        while (j < text.length && /\s/.test(text[j])) j += 1;
        const after = text[j];
        const closes =
          after === undefined ||
          after === "," ||
          after === "}" ||
          after === "]" ||
          (stringRole === "key" && after === ":");
        if (closes) {
          inString = false;
          out += c;
        } else {
          out += '\\"';
        }
        continue;
      }
      if (c === "\n" || c === "\r") {
        out += "\\n";
        continue;
      }
      out += c;
      continue;
    }
    if (c === '"') {
      let k = out.length - 1;
      while (k >= 0 && /\s/.test(out[k])) k -= 1;
      stringRole = out[k] === ":" ? "value" : "key";
      inString = true;
      out += c;
      continue;
    }
    if (c === "{" || c === "[") stack.push(c);
    else if ((c === "}" && stack[stack.length - 1] === "{") || (c === "]" && stack[stack.length - 1] === "[")) {
      stack.pop();
    }
    out += c;
  }
  if (inString) {
    let closers = "";
    while (out.endsWith("}") || out.endsWith("]")) {
      closers = out.slice(-1) + closers;
      out = out.slice(0, -1);
    }
    let quoteAt = -1;
    for (let i = out.length - 1; i >= 0; i--) {
      if (out[i] !== '"') continue;
      let slashes = 0;
      for (let k = i - 1; k >= 0 && out[k] === "\\"; k--) slashes += 1;
      if (slashes % 2 === 0) {
        quoteAt = i;
        break;
      }
    }
    const value = out.slice(quoteAt + 1);
    const pending = [];
    let valueEscaped = false;
    for (const ch of value) {
      if (valueEscaped) {
        valueEscaped = false;
        continue;
      }
      if (ch === "\\") {
        valueEscaped = true;
        continue;
      }
      if (ch === "{") pending.push("}");
      else if (ch === "[") pending.push("]");
      else if ((ch === "}" || ch === "]") && pending[pending.length - 1] === ch) pending.pop();
    }
    while (pending.length && closers.startsWith(pending[pending.length - 1])) {
      out += pending.pop();
      closers = closers.slice(1);
    }
    out += '"';
    for (const closer of closers) {
      const open = stack[stack.length - 1];
      if ((closer === "}" && open === "{") || (closer === "]" && open === "[")) {
        stack.pop();
        out += closer;
      }
    }
  }
  while (stack.length) {
    out += stack.pop() === "{" ? "}" : "]";
  }
  return out;
